class TargetInputError(ValueError):
    pass

def target_from_text(text):
    try:
        value = int(text)
    except ValueError as error:
        raise TargetInputError('target must be an integer') from error
    else:
        if value < 1:
            raise TargetInputError('target must be positive')
        return value

for text in ['3', 'many']:
    try:
        print(target_from_text(text))
    except TargetInputError as error:
        print(f'Check input: {error}')
    finally:
        print('record finished')

